class Config:
    def __init__(self):
        self.host = "localhost"
        self.port = 8080

def get_property(obj, prop_name, default=None):
    if hasattr(obj, prop_name):
        return obj.__class__.__name__
    else:
        return default

c = Config()
print(get_property(c, "port"), get_property(c, "user"))

